package com.foodbridge.donation;
import jakarta.validation.constraints.*;import java.time.LocalDateTime;import java.util.HashSet;import java.util.Set;
public class DonationForm {
    @NotBlank @Size(max=160) private String foodName="";@NotBlank @Size(max=2000) private String description="";@NotBlank @Size(max=120) private String donorOrganization="";@NotBlank @Size(max=300) private String pickupAddress="";@Min(1) @Max(100000) private int quantity=1;@NotNull @Future private LocalDateTime pickupStart=LocalDateTime.now().plusHours(1);@NotNull @Future private LocalDateTime safetyCutoff=LocalDateTime.now().plusHours(4);private Set<DietaryTag> dietaryTags=new HashSet<>();
    public String getFoodName(){return foodName;}public void setFoodName(String v){foodName=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getDonorOrganization(){return donorOrganization;}public void setDonorOrganization(String v){donorOrganization=v;}public String getPickupAddress(){return pickupAddress;}public void setPickupAddress(String v){pickupAddress=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}public LocalDateTime getPickupStart(){return pickupStart;}public void setPickupStart(LocalDateTime v){pickupStart=v;}public LocalDateTime getSafetyCutoff(){return safetyCutoff;}public void setSafetyCutoff(LocalDateTime v){safetyCutoff=v;}public Set<DietaryTag> getDietaryTags(){return dietaryTags;}public void setDietaryTags(Set<DietaryTag> v){dietaryTags=v==null?new HashSet<>():v;}
    public DonationListingRequest toRequest(){return new DonationListingRequest(foodName,description,donorOrganization,pickupAddress,quantity,pickupStart,safetyCutoff,dietaryTags);}
}
